    .filter(isRawFormerName)
    .slice(0, MAX_FORMER_NAMES)
    .map(({ name, until, sessionId }) => ({
      name: sliceUnits(name, MAX_SESSION_NAME),
      until,
      ...(sessionId !== undefined && { sessionId: sliceUnits(sessionId, MAX_SESSION_NAME) }),
    }))
